INSERT INTO corridors (id, code, name, description, corridor_type, affected_countries, base_risk_score, india_dependency_share, is_active) VALUES (1, 'HORMUZ', 'Strait of Hormuz', 'Strategic chokepoint between Persian Gulf and Gulf of Oman. ~20% of global oil transit. Critical for Iraq, Saudi Arabia, UAE, Kuwait, Qatar exports to India.', 'CHOKEPOINT', ARRAY['IRQ','SAU','ARE','KWT','IRN','QAT'], 0.60, 0.42, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO corridors (id, code, name, description, corridor_type, affected_countries, base_risk_score, india_dependency_share, is_active) VALUES (2, 'RED_SEA', 'Red Sea / Bab el-Mandeb', 'Connects Gulf of Aden to Suez Canal. Houthi attacks since 2023 have disrupted shipping. Affects Mediterranean-routed crude to India.', 'CHOKEPOINT', ARRAY['EGY'], 0.50, 0.05, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO corridors (id, code, name, description, corridor_type, affected_countries, base_risk_score, india_dependency_share, is_active) VALUES (3, 'SUEZ', 'Suez Canal', 'Connects Red Sea to Mediterranean. Critical for European crude flows. Some India-bound crude from Mediterranean sources.', 'CHOKEPOINT', ARRAY['EGY'], 0.35, 0.03, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO corridors (id, code, name, description, corridor_type, affected_countries, base_risk_score, india_dependency_share, is_active) VALUES (4, 'MALACCA', 'Strait of Malacca', 'Connects Indian Ocean to South China Sea. Critical for East Asian energy supply. Less critical for India crude imports.', 'CHOKEPOINT', ARRAY['MYS'], 0.25, 0.02, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO corridors (id, code, name, description, corridor_type, affected_countries, base_risk_score, india_dependency_share, is_active) VALUES (5, 'RUSSIA', 'Russia Supplier Corridor', 'Russia as a supplier corridor. Crude exported from Baltic (Primorsk/Ust-Luga) and Pacific (Kozmino/ESPO). Subject to Western sanctions/price cap since 2022.', 'SUPPLIER_CORRIDOR', ARRAY['RUS'], 0.55, 0.37, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO corridors (id, code, name, description, corridor_type, affected_countries, base_risk_score, india_dependency_share, is_active) VALUES (6, 'CAPE', 'Cape of Good Hope', 'Alternate routing around Africa. Used when Hormuz/Red Sea/Suez are disrupted. Significantly longer transit (~3x Hormuz route).', 'REGIONAL', NULL, 0.10, 0.00, TRUE) ON CONFLICT (id) DO NOTHING;
